#define NUM 7
#define PI  3.14159265359

//--------------------------------------------------
// The original "pal" function
vec3 pal( float t, vec3 a, vec3 b, vec3 c, vec3 d )
{
    return a + b*cos(6.28318*(c*t + d));
}

// Store the original sets of (a, b, c, d) for each of the 7 rows
vec3 A[NUM];
vec3 B[NUM];
vec3 C[NUM];
vec3 D[NUM];

void initPalettes()
{
    // row 0
    A[0] = vec3(0.5,0.5,0.5);   B[0] = vec3(0.5,0.5,0.5);
    C[0] = vec3(1.0,1.0,1.0);   D[0] = vec3(0.0,0.33,0.67);

    // row 1
    A[1] = vec3(0.5,0.5,0.5);   B[1] = vec3(0.5,0.5,0.5);
    C[1] = vec3(1.0,1.0,1.0);   D[1] = vec3(0.0,0.10,0.20);

    // row 2
    A[2] = vec3(0.5,0.5,0.5);   B[2] = vec3(0.5,0.5,0.5);
    C[2] = vec3(1.0,1.0,1.0);   D[2] = vec3(0.3,0.20,0.20);

    // row 3
    A[3] = vec3(0.5,0.5,0.5);   B[3] = vec3(0.5,0.5,0.5);
    C[3] = vec3(1.0,1.0,0.5);   D[3] = vec3(0.8,0.90,0.30);

    // row 4
    A[4] = vec3(0.5,0.5,0.5);   B[4] = vec3(0.5,0.5,0.5);
    C[4] = vec3(1.0,0.7,0.4);   D[4] = vec3(0.0,0.15,0.20);

    // row 5
    A[5] = vec3(0.5,0.5,0.5);   B[5] = vec3(0.5,0.5,0.5);
    C[5] = vec3(2.0,1.0,0.0);   D[5] = vec3(0.5,0.20,0.25);

    // row 6
    A[6] = vec3(0.8,0.5,0.4);   B[6] = vec3(0.2,0.4,0.2);
    C[6] = vec3(2.0,1.0,1.0);   D[6] = vec3(0.0,0.25,0.25);
}

// Get color for band i, at "parameter" t
vec3 getBandColor( int i, float t )
{
    int idx = i % NUM;
    return pal(t, A[idx], B[idx], C[idx], D[idx]);
}

// A simple rule for over/under at intersections:
// If (horizontalIndex + verticalIndex) is even => horizontal is on top
bool horizontalOver(int i, int j)
{
    return (((i + j) % 2) == 0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Initialize palette arrays
    initPalettes();

    // Normalized coordinates
    vec2 uv = fragCoord.xy / iResolution.xy;

    // The thickness of each strand
    float halfWidth = 0.08;

    // Find which horizontal band we're closest to
    float minHdist = 1e9;
    int   hIndex   = -1;
    for(int i=0; i<NUM; i++)
    {
        // The center of band i is at (i + 0.5)/NUM
        float centerY = (float(i)+0.5)/float(NUM);

        float distY = abs(uv.y - centerY);
        if(distY < minHdist)
        {
            minHdist = distY;
            hIndex   = i;
        }
    }

    // Find which vertical band we're closest to
    float minVdist = 1e9;
    int   vIndex   = -1;
    for(int j=0; j<NUM; j++)
    {
        // The center of band j is at (j + 0.5)/NUM
        float centerX = (float(j)+0.5)/float(NUM);

        float distX = abs(uv.x - centerX);
        if(distX < minVdist)
        {
            minVdist = distX;
            vIndex   = j;
        }
    }

    // Check if we’re within the thickness of those bands
    bool inHorizontal = (minHdist < halfWidth);
    bool inVertical   = (minVdist < halfWidth);

    // Final color
    vec3 col = vec3(0.0);

    // Horizontal only
    if(inHorizontal && !inVertical)
    {
        // Colors move across x + time
        float tH = uv.x + iTime;
        col = getBandColor(hIndex, tH);
    }
    // Vertical only
    else if(inVertical && !inHorizontal)
    {
        // Colors move across y + time
        float tV = uv.y + iTime;
        col = getBandColor(vIndex, tV);
    }
    // Intersection => choose who’s on top
    else if(inHorizontal && inVertical)
    {
        if(horizontalOver(hIndex, vIndex))
        {
            // horizontal on top
            float tH = uv.x + iTime;
            col = getBandColor(hIndex, tH);
        }
        else
        {
            // vertical on top
            float tV = uv.y + iTime;
            col = getBandColor(vIndex, tV);
        }
    }

    fragColor = vec4(col, 1.0);
}
